 Agent Backend Implementation

Below is the complete, singlefile Python implementation (agent.py) that encompasses the core loop, context management, tool execution, and Requesty AI LLM routing.[1][2]

python
import os
import sys
import json
import time
import subprocess
import logging
import asyncio
from typing import Dict, List, Any, Optional
from openai import OpenAI

# ---------------------------------------------------------------------------
# Configuration & Setup
# ---------------------------------------------------------------------------
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Requesty AI unified API gateway [web:2]
REQUESTY_BASE_URL = os.getenv("REQUESTY_BASE_URL", "https://router.requesty.ai/v1")
REQUESTY_API_KEY = os.getenv("REQUESTY_API_KEY")

if not REQUESTY_API_KEY:
    raise ValueError("REQUESTY_API_KEY environment variable is required.")

client = OpenAI(
    base_url=REQUESTY_BASE_URL,
    api_key=REQUESTY_API_KEY
)

# Model Routing Configuration [web:2, web:11, web:14, web:16]
MODELS = {
    "planner": "zai/glm-5.2",
    "coder": "openai-responses/gpt-5.6-sol",
    "vision": "google/gemini-3.6-flash",
    "sensitive": "xai/grok-4.3",
    "long_context": "minimaxai/minimax-m3"
}

# ---------------------------------------------------------------------------
# VM and File Operations (CodeAct Paradigm)
# ---------------------------------------------------------------------------
def execute_command(command: str) -> str:
    """Execute a shell command in the VM (CodeAct style)."""
    try:
        logger.info(f"Executing command: {command}")
        result = subprocess.run(
            command, 
            shell=True, 
            check=False, 
            capture_output=True, 
            text=True,
            timeout=120
        )
        output = result.stdout
        if result.stderr:
            output += f"\nSTDERR:\n{result.stderr}"
        return output
    except Exception as e:
        return f"Error executing command: {str(e)}"

def read_file(filepath: str) -> str:
    """Read contents of a file to use FS as external memory."""
    try:
        with open(filepath, 'r') as f:
            return f.read()
    except Exception as e:
        return f"Error reading file {filepath}: {str(e)}"

def write_file(filepath: str, content: str) -> str:
    """Write content to a file."""
    try:
        with open(filepath, 'w') as f:
            f.write(content)
        return f"Successfully wrote to {filepath}"
    except Exception as e:
        return f"Error writing to {filepath}: {str(e)}"

# ---------------------------------------------------------------------------
# Tool Definitions
# ---------------------------------------------------------------------------
TOOLS = [
    {
        "type": "function",
        "function": {
            "name": "execute_command",
            "description": "Execute a Unix CLI command or bash script. Use piping and chaining for complex tasks.",
            "parameters": {
                "type": "object",
                "properties": {
                    "command": {"type": "string", "description": "The bash command to execute."}
                },
                "required": ["command"],
                "additionalProperties": False
            },
            "strict": True
        }
    },
    {
        "type": "function",
        "function": {
            "name": "read_file",
            "description": "Read file contents. Use this to load data from the external filesystem memory.",
            "parameters": {
                "type": "object",
                "properties": {
                    "filepath": {"type": "string", "description": "Path to the file."}
                },
                "required": ["filepath"],
                "additionalProperties": False
            },
            "strict": True
        }
    },
    {
        "type": "function",
        "function": {
            "name": "write_file",
            "description": "Write data or code to a file.",
            "parameters": {
                "type": "object",
                "properties": {
                    "filepath": {"type": "string", "description": "Path to the file."},
                    "content": {"type": "string", "description": "Content to write."}
                },
                "required": ["filepath", "content"],
                "additionalProperties": False
            },
            "strict": True
        }
    }
]

# ---------------------------------------------------------------------------
# Core Agent System
# ---------------------------------------------------------------------------
class AutonomousAgent:
    def __init__(self, task: str):
        self.task = task
        self.todo_file = "todo.md"
        self.messages = []
        self._initialize_context()

    def _initialize_context(self):
        """Setup initial context and goal tracking."""
        system_prompt = (
            "You are an autonomous AI agent operating in a NixOS microVM. "
            "You follow the CodeAct paradigm: prefer executing Unix commands and Python scripts over raw logic. "
            "Maintain a dynamic todo list in 'todo.md' to track subgoals. "
            "Use the filesystem as your primary memory. "
            "Rely on STDERR for dynamic error recovery."
        )
        self.messages.append({"role": "system", "content": system_prompt})
        self.messages.append({"role": "user", "content": f"Primary Task: {self.task}"})
        write_file(self.todo_file, f"# Task Todo List\n- [ ] {self.task}")

    def select_model(self, current_intent: str) -> str:
        """Dynamically route to the best model via Requesty AI [web:2]."""
        if "code" in current_intent or "script" in current_intent:
            return MODELS["coder"]
        elif "pdf" in current_intent or "large" in current_intent:
            return MODELS["long_context"]
        else:
            return MODELS["planner"]

    def execute_tool_call(self, tool_call) -> str:
        """Map LLM tool calls to local Python functions."""
        name = tool_call.function.name
        args = json.loads(tool_call.function.arguments)

        if name == "execute_command":
            return execute_command(args["command"])
        elif name == "read_file":
            return read_file(args["filepath"])
        elif name == "write_file":
            return write_file(args["filepath"], args["content"])
        else:
            return f"Error: Unknown function {name}"

    def step(self) -> bool:
        """Perform one iteration of the Observe-Orient-Decide-Act loop."""
        try:
            # Re-inject goal state to prevent drift
            todo_state = read_file(self.todo_file)
            context_msg = f"Current Todo State:\n{todo_state}"

            # Temporary context injection (KV-Cache friendly append)
            temp_messages = self.messages + [{"role": "system", "content": context_msg}]

            model = self.select_model(str(self.messages[-1]))
            logger.info(f"Routing request to model: {model}")

            response = client.chat.completions.create(
                model=model,
                messages=temp_messages,
                tools=TOOLS,
                tool_choice="auto",
                temperature=0.2,
                extra_body={"requesty": {"auto_cache": True}} # Enable Requesty caching [web:2]
            )

            message = response.choices[0].message
            self.messages.append(message)

            if message.tool_calls:
                # Execute selected tool (single most appropriate tool per iteration)
                for tool_call in message.tool_calls:
                    logger.info(f"Executing tool: {tool_call.function.name}")
                    result = self.execute_tool_call(tool_call)
                    self.messages.append({
                        "role": "tool",
                        "tool_call_id": tool_call.id,
                        "name": tool_call.function.name,
                        "content": result
                    })
                return True # Continue loop

            elif "TASK_COMPLETE" in message.content:
                logger.info("Agent signaled task completion.")
                return False # End loop

            else:
                # If no tool called and not complete, prompt agent to take action
                self.messages.append({"role": "user", "content": "Please execute an action or output 'TASK_COMPLETE'."})
                return True

        except Exception as e:
            logger.error(f"Error in agent step: {e}")
            self.messages.append({"role": "user", "content": f"System error occurred: {e}. Please recover."})
            return True

    def run(self):
        """Outer loop for continuous execution."""
        logger.info(f"Starting agent task: {self.task}")
        running = True
        step_count = 0
        max_steps = 50 # Safeguard

        while running and step_count < max_steps:
            logger.info(f"--- Step {step_count + 1} ---")
            running = self.step()
            step_count += 1

        logger.info("Agent execution finished.")

# ---------------------------------------------------------------------------
# Entry Point
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python agent.py '<task_description>'")
        sys.exit(1)

    task_prompt = sys.argv[1]
    agent = AutonomousAgent(task_prompt)
    agent.run()


 Key Implementation Details
 Requesty Router Integration: The script uses the standard openai SDK but points the base_url to https://router.requesty.ai/v1. This single gateway allows seamless routing between zai/glm-5.2, openai-responses/gpt-5.6-sol, and minimaxai/minimax-m3 just by changing the model string parameter. Prompt caching is enabled via the extra_body payload.[3][4][1]
 CodeAct Paradigm: The system relies heavily on the execute_command tool. Instead of defining explicit tools for package management or network requests, the model is expected to use standard Unix CLI pipelines (e.g., grep, curl, apt) and parse the stdout/stderr for dynamic error correction.[2]
 Memory Management: The todo.md file acts as the persistent goal tracker, which is read and injected into the system context on every loop to prevent hallucination or goal drift. Longform context (like PDFs) should be read into the file system via Unix commands, bypassing the KV cache bottleneck.
